/**
 * How this workspace member reaches the workspace broker, and how it is called.
 *
 * Generated by `setu`. The CLI owns this file and rewrites it from
 * setu.workspace.json, so edits here are lost. Change the broker with
 * `setu workspace broker <name>` and this member's RPC style with
 * `setu workspace rpc <member> <http|grpc>`.
 *
 * @module
 */

import type { RuntimeOptions } from '@setu-ts/runtime';
import type { IPlugin } from '@setu-ts/common';
import type { MessagingPluginOptions } from '@setu-ts/messaging-plugin';
import type { QueuePluginOptions } from '@setu-ts/queue-plugin';
import { GrpcPlugin } from '@setu-ts/grpc-plugin';

/**
 * Serve gRPC over cleartext HTTP/2 beside HTTP/1.1 on the member's port.
 * For TLS use RuntimePlugin({ http2: { key, cert } }) with discovery secure: true.
 * On Bun HTTP/2 uses the Node adapter; WebSockets then need the optional ws peer.
 *
 * @returns The runtime options for this member's RPC style
 * @since 0.13.0
 */
export function runtimeOptions(): RuntimeOptions {
  return { http2: true };
}

/**
 * The memory broker's `MessagingPlugin` options.
 *
 * @returns The options, rendered from setu.workspace.json
 */
export function messagingOptions(): MessagingPluginOptions {
  return {};
}

/**
 * The `QueuePlugin` options: in memory, since the queue has no memory arm.
 *
 * @returns The options, rendered from setu.workspace.json
 */
export function queueOptions(): QueuePluginOptions {
  return {};
}

/**
 * The plugins this member's RPC style adds: `GrpcPlugin`, mounted under `/grpc`.
 *
 * @returns The plugins to register
 */
export function transportPlugins(): readonly IPlugin[] {
  return [GrpcPlugin({ basePath: '/grpc' })];
}
